const entrada = $input.first().json;
const clientes = entrada.body.clientes;

return clientes.map(cliente => ({
  json: {
    nome: cliente.nome,
    email: cliente.email,
    saldo: cliente.saldo,
    perfil: cliente.perfil
  }
}));

const investimentos = [
  { perfil: "Conservador", produto: "Poupança", minimo: 100, rentabilidade: "6.2%" },
  { perfil: "Conservador", produto: "CDB Liquidez Diária", minimo: 1000, rentabilidade: "12.5%" },
  { perfil: "Conservador", produto: "Tesouro Selic", minimo: 500, rentabilidade: "13.0%" },
  { perfil: "Moderado", produto: "CDB Prefixado", minimo: 1000, rentabilidade: "14.0%" },
  { perfil: "Moderado", produto: "Fundo Multimercado", minimo: 5000, rentabilidade: "16.0%" },
  { perfil: "Moderado", produto: "Tesouro IPCA+", minimo: 1000, rentabilidade: "IPCA+6.0%" },
  { perfil: "Arrojado", produto: "Ações ETF", minimo: 500, rentabilidade: "Variável" },
  { perfil: "Arrojado", produto: "Fundo de Ações", minimo: 10000, rentabilidade: "Variável" },
  { perfil: "Arrojado", produto: "Criptomoedas", minimo: 100, rentabilidade: "Variável" }
];

function converterSaldo(valor) {
  return Number(
    String(valor ?? "")
      .replace("R$", "")
      .replace(/\./g, "")
      .replace(",", ".")
      .trim()
  );
}

return $input.all().map(item => {
  const cliente = item.json;
  const saldo = converterSaldo(cliente.saldo);

  const opcoes = investimentos.filter(produto =>
    produto.perfil === cliente.perfil &&
    saldo >= produto.minimo
  );

  const mensagem = opcoes.length
    ? `Olá, ${cliente.nome}! Encontramos ${opcoes.length} opção(ões) compatíveis com seu perfil e saldo: ${opcoes.map(p => p.produto).join(", ")}.`
    : `Olá, ${cliente.nome}! Não encontramos opções do catálogo com investimento mínimo compatível com seu saldo atual.`;

  return {
    json: {
      ...cliente,
      opcoesInvestimento: opcoes,
      mensagem
    }
  };
});

const csv = $('HTTP Request').first().json.data;

const linhas = csv.trim().split(/\r?\n/);
const cabecalho = linhas[0].split(",");

const investimentos = linhas.slice(1).map(linha => {
  const valores = linha.split(",");

  return {
    perfil: valores[0],
    produto: valores[1],
    minimo: Number(valores[2]),
    rentabilidade: valores[3]
  };
});

